import { block } from "./bank-utils.mjs";
const groups = [];
const add = (topic, text, tasks) => groups.push(block(topic, `Síntese didática autoral; não é transcrição de documento histórico:\n${text}`, tasks));
add("Agricultura, sedentarização e diversidade", "A adoção de agricultura e criação de animais em diferentes regiões modificou a produção de alimentos. Em alguns grupos, favoreceu assentamentos mais permanentes, armazenamento e especialização do trabalho. A mudança não ocorreu de uma só vez em toda parte e não eliminou automaticamente coleta, caça ou conflitos. Vestígios arqueológicos precisam ser interpretados junto ao contexto em que foram encontrados.", [
 ["Qual interpretação evita transformar essas mudanças em uma evolução única e inevitável de todas as sociedades?", "Reconhecer trajetórias diversas e combinações entre atividades produtivas.", ["Considerar que a agricultura surgiu simultaneamente em todas as regiões.", "Tomar todo assentamento como prova de ausência de coleta e caça.", "Supor que o armazenamento eliminou automaticamente desigualdades.", "Definir a especialização como resultado exclusivo de uma técnica única."], "A síntese destaca diversidade de tempo e combinação de atividades. Agricultura pode favorecer permanência e especialização sem impor um mesmo caminho a todos os grupos."],
 ["Que relação entre produção e organização social é compatível com a síntese?", "Estoque e permanência podem favorecer divisão de tarefas e novas formas de distribuir recursos.", ["Produzir alimentos torna toda distribuição necessariamente igualitária.", "Armazenar alimentos impede o desenvolvimento de tarefas especializadas.", "O assentamento permanente torna impossível qualquer troca entre grupos.", "A criação de animais determina que toda autoridade desapareça."], "Armazenamento altera a disponibilidade de recursos e pode permitir especialização. Isso abre possibilidades de organização, mas não prova igualdade, isolamento ou ausência de autoridade."],
 ["Um recipiente com restos de grãos, encontrado isoladamente, permite qual conclusão mais prudente?", "Houve contato com grãos; cultivo local e forma de organização exigem outros vestígios.", ["Todos os habitantes eram agricultores especializados.", "O objeto comprova ausência de comércio entre regiões.", "A sociedade já possuía necessariamente escrita e Estado centralizado.", "Os grãos provam que o grupo desconhecia alimentos de origem animal."], "Um vestígio isolado não distingue cultivo local, coleta, troca ou múltiplas funções. A interpretação precisa de contexto e associação a outras evidências."],
 ["Qual pesquisa ajuda a diferenciar produção local de circulação de alimentos por troca?", "Comparar restos botânicos, instrumentos, áreas de cultivo e proveniência dos materiais.", ["Usar apenas o tamanho de um recipiente para determinar toda economia.", "Contar os objetos sem registrar localização ou período.", "Presumir cultivo local porque há grãos em um único vestígio.", "Descartar sementes de espécies conhecidas para evitar diversidade."], "Um conjunto contextualizado de vestígios permite testar hipóteses distintas. A localização, o período e a proveniência ajudam a relacionar produção e circulação."],
 ["Que mudança poderia coexistir com a permanência de práticas anteriores?", "Cultivar parte dos alimentos e continuar coleta ou caça de outras fontes.", ["Adotar agricultura significa abandonar toda outra fonte de alimento.", "Domesticar animais impede a manutenção de redes de troca.", "Construir um assentamento elimina qualquer deslocamento sazonal.", "Armazenar grãos exige extinguir toda diversidade alimentar."], "Mudanças produtivas podem combinar-se com práticas já existentes. A síntese rejeita a ideia de substituição total e imediata de todas as atividades."],
]);
add("Democracia ateniense e cidadania", "Na Atenas clássica, cidadãos homens adultos participavam de instituições políticas. Mulheres, estrangeiros residentes e pessoas escravizadas não possuíam os mesmos direitos de participação. A democracia daquela cidade não pode ser identificada sem distinções com o sufrágio amplo contemporâneo; tampouco sua exclusão anula a importância histórica das instituições de participação entre cidadãos.", [
 ["Qual comparação com o presente preserva a especificidade histórica?", "Havia participação política direta entre cidadãos, mas a cidadania excluía amplos grupos.", ["A participação era universal, pois todos os moradores eram cidadãos.", "A presença de exclusões significa que não existia qualquer instituição participativa.", "As mulheres votavam somente quando os homens estavam ausentes.", "Estrangeiros residentes exerciam necessariamente os mesmos direitos dos cidadãos."], "É preciso distinguir participação dos cidadãos e acesso à cidadania. Reconhecer instituições democráticas não implica atribuir universalidade aos direitos daquela sociedade."],
 ["Um texto que define apenas os direitos dos cidadãos permite concluir o quê sobre toda a população?", "Descreve um grupo jurídico específico e não representa automaticamente todos os habitantes.", ["Todos os habitantes possuíam os direitos descritos.", "A população era formada exclusivamente por homens adultos livres.", "A existência de direitos dos cidadãos prova ausência de escravidão.", "As regras citadas não produziam qualquer efeito sobre grupos excluídos."], "A categoria cidadão tem abrangência histórica delimitada. Os direitos de um grupo não podem ser estendidos automaticamente a estrangeiros, mulheres ou pessoas escravizadas."],
 ["Que diferença entre participação e representação é relevante nesse exemplo?", "Cidadãos podiam deliberar diretamente em instituições, diferindo da escolha de representantes como forma predominante de participação atual.", ["Participação direta exige que toda pessoa do território seja cidadã.", "Toda eleição moderna elimina qualquer possibilidade de deliberação coletiva.", "A democracia ateniense consistia apenas em voto para presidentes nacionais.", "Representação e participação direta são termos idênticos em qualquer sociedade."], "A distinção trata do modo de decisão entre os habilitados. Ela não resolve, por si só, a abrangência da cidadania nem impede combinações contemporâneas de participação e representação."],
 ["Qual afirmação caracteriza um anacronismo ao interpretar Atenas?", "Atribuir aos atenienses o mesmo conceito jurídico de sufrágio universal de uma Constituição contemporânea.", ["Examinar regras de participação no contexto da cidade.", "Identificar grupos excluídos dos direitos políticos.", "Comparar instituições antigas e atuais explicitando suas diferenças.", "Investigar como a categoria cidadão era definida."], "Anacronismo projeta conceitos ou instituições de outro período sem contextualização. Comparações são possíveis quando preservam diferenças e não tratam o presente como descrição do passado."],
 ["Que tipo de evidência complementa um discurso de elogio da cidadania?", "Registros de regras, práticas e exclusões que permitam comparar o ideal declarado com o acesso efetivo.", ["Somente outro elogio com as mesmas palavras.", "A opinião de um leitor atual sem consultar práticas antigas.", "Uma definição moderna aplicada sem mudanças ao passado.", "Um mapa da cidade usado como prova suficiente de direitos universais."], "Um discurso apresenta perspectiva e finalidade. Compará-lo a regras e práticas ajuda a avaliar quem participava e como os ideais se relacionavam às experiências sociais."],
]);
add("Roma, expansão e conflitos sociais", "A expansão romana ampliou territórios, circulação de riquezas e uso de trabalho escravizado. Proprietários concentraram terras em algumas regiões, enquanto grupos plebeus enfrentavam disputas por recursos e participação. A passagem da República ao Império envolveu conflitos e concentração de poder, não apenas um aumento de tamanho do território.", [
 ["Que relação explica por que expansão territorial podia coexistir com conflitos internos?", "Benefícios e custos da expansão eram distribuídos de forma desigual entre grupos.", ["Toda riqueza conquistada era dividida igualmente entre os moradores.", "A conquista impedia o uso de trabalho escravizado.", "O aumento do território eliminava disputas por terra.", "A circulação de riquezas tornava desnecessária qualquer organização política."], "A expansão podia beneficiar grupos de modo diferente e alterar relações de trabalho e propriedade. Crescimento territorial não equivale a igualdade social ou ausência de disputas."],
 ["Que transformação política distingue a concentração imperial de uma simples mudança geográfica?", "Ampliação e centralização de autoridade, associadas a conflitos das instituições republicanas.", ["Apenas troca do nome do território, sem alteração de poder.", "Desaparecimento imediato de todas as instituições anteriores.", "Distribuição automática de autoridade a todos os habitantes conquistados.", "Substituição de qualquer hierarquia por decisões universais diretas."], "O processo imperial envolve relações de autoridade e disputas políticas. Não se reduz à dimensão do território nem implica extinção imediata de toda instituição anterior."],
 ["Um relato de vitória militar basta para comprovar melhoria de vida de todos os habitantes?", "Não; é preciso investigar distribuição de recursos, tributação e formas de trabalho.", ["Sim, pois vitória implica igualdade econômica.", "Sim, porque relatos militares descrevem necessariamente todos os grupos.", "Não, porque conquistas nunca produziram riqueza.", "Sim, se o autor do relato ocupava um cargo de comando."], "Um relato de vitória tem recorte e perspectiva. A experiência dos grupos depende de recursos, custos e posições sociais que não são comprovados pela celebração militar."],
 ["Qual mudança pode relacionar concentração fundiária a tensões entre grupos?", "Maior controle de terras por proprietários poderosos e disputa de pequenos produtores por acesso a recursos.", ["A concentração elimina qualquer diferença entre proprietários e trabalhadores.", "Grandes propriedades asseguram acesso igual de todos à terra.", "A propriedade territorial deixa de ter significado social após conquistas.", "A presença de trabalho escravizado comprova ausência de proprietários livres."], "Controle concentrado de recursos pode alterar oportunidades e gerar tensão. Trabalho escravizado e produtores livres podem coexistir em relações diferentes com a terra."],
 ["Que procedimento evita reduzir a história romana a uma causa única?", "Relacionar expansão, trabalho, propriedade e disputas institucionais em seus períodos específicos.", ["Explicar toda transformação apenas pelo número de quilômetros conquistados.", "Ignorar conflitos porque houve crescimento econômico.", "Aplicar uma descrição única da Roma antiga a todos os séculos.", "Considerar relatos de governantes como retrato completo da população."], "Processos políticos e sociais se articulam e mudam ao longo do tempo. Evitar monocausalidade exige examinar relações e períodos, não uma variável isolada."],
]);
add("Relações feudais e obrigações", "Em partes da Europa medieval, senhores controlavam terras e exerciam poderes locais. Camponeses podiam prestar trabalho e entregar parte da produção em troca de acesso à terra e proteção sob relações desiguais. Vassalagem ligava membros da elite por compromissos de fidelidade e serviço; não era a mesma relação que a servidão camponesa. A organização variava entre regiões e períodos.", [
 ["Qual distinção evita confundir vassalagem e servidão?", "Vassalagem articulava compromissos entre membros da elite; servidão envolvia obrigações de camponeses ligados à terra.", ["Ambas designavam apenas contratos salariais iguais aos atuais.", "Vassalagem era a participação de todos os camponeses em eleições nacionais.", "Servidão era exclusivamente uma aliança militar entre reis independentes.", "As duas relações dispensavam qualquer desigualdade de poder."], "A síntese distingue posições e tipos de obrigação. Relações pessoais de elite e obrigações camponesas não são categorias equivalentes, mesmo quando coexistem."],
 ["Que interpretação do trabalho e entrega de produção preserva a desigualdade descrita?", "O acesso à terra podia implicar obrigações impostas dentro de uma relação de dependência.", ["A presença de proteção prova igualdade jurídica entre senhor e camponês.", "A entrega de produção era sempre uma compra livre em mercado nacional integrado.", "As obrigações eliminavam o controle senhorial da terra.", "A produção era entregue apenas porque não havia uso para os alimentos."], "Proteção e acesso à terra não tornam a relação igualitária. Obrigações econômicas e poderes locais podem reforçar dependência entre os grupos."],
 ["Por que não se deve tratar a síntese como descrição idêntica de toda a Europa medieval?", "Porque relações e poderes locais tinham variações regionais e temporais.", ["Porque a Idade Média ocorreu apenas em uma única cidade.", "Porque nenhuma sociedade medieval tinha agricultura.", "Porque a existência de senhores prova um Estado nacional uniforme em toda Europa.", "Porque a vassalagem só pode existir fora de qualquer período histórico."], "Uma caracterização geral não elimina diversidade. O estudo precisa identificar a região, o momento e as formas concretas de poder e obrigação."],
 ["Qual informação seria útil ao examinar uma obrigação de entrega de parte da colheita?", "A proporção entregue, as condições de acesso à terra e os poderes de cobrança do senhor.", ["A cor do pergaminho, sem investigar o conteúdo do acordo.", "Apenas o número de palavras de um documento.", "Uma definição de salário atual aplicada sem comparação.", "O nome de um castelo sem contexto sobre os trabalhadores."], "Condições materiais e poderes de cobrança ajudam a compreender a relação. Características isoladas do suporte documental não explicam as obrigações sociais."],
 ["Qual afirmação projeta indevidamente uma instituição contemporânea sobre a relação descrita?", "Dizer que todo vínculo camponês equivalia a emprego assalariado com os mesmos direitos trabalhistas atuais.", ["Investigar formas de dependência econômica.", "Distinguir elites e trabalhadores camponeses.", "Examinar variações das obrigações entre regiões.", "Estudar como proteção e acesso à terra se relacionavam."], "A equivalência sem contexto entre dependência medieval e emprego atual apaga diferenças de direito, poder e organização econômica. Comparações precisam explicitar essas diferenças."],
]);
add("Renascimento e circulação de conhecimento", "Mudanças culturais associadas ao Renascimento envolveram interesse por referências clássicas, observação, experimentação em certos campos e novas formas de representar pessoas e espaços. A imprensa ampliou possibilidades de circulação de textos, mas o acesso não foi imediato nem igual para toda a população. A valorização do ser humano coexistiu com religiosidade e relações de poder.", [
 ["Qual interpretação distingue humanismo de abandono universal da religião?", "A valorização de capacidades humanas podia coexistir com crenças e instituições religiosas.", ["O humanismo eliminou todas as crenças religiosas em todas as regiões.", "A referência clássica impediu qualquer investigação da natureza.", "A circulação de textos tornou toda pessoa leitora imediatamente.", "A religiosidade prova que não houve mudanças culturais."], "O Renascimento não é ruptura total e uniforme com a religião. Mudanças no interesse intelectual e na representação humana podem coexistir com crenças e poderes existentes."],
 ["Como a imprensa podia favorecer debates sem garantir igualdade de acesso?", "Ampliando reprodução e circulação de textos, ainda limitadas por alfabetização, custo e controle.", ["Eliminando automaticamente censura e desigualdade de alfabetização.", "Tornando desnecessária a existência de leitores.", "Restringindo toda comunicação a um único exemplar manuscrito.", "Garantindo a cada habitante acesso gratuito a todos os livros."], "A tecnologia modifica circulação, mas seus efeitos dependem de condições sociais e políticas. Maior reprodução não comprova acesso universal ou ausência de controle."],
 ["Uma pintura que emprega perspectiva permite investigar qual dimensão de mudança?", "Técnicas de representação do espaço e escolhas artísticas em seu contexto.", ["A eliminação completa de relações sociais desiguais.", "O fim de toda religiosidade entre os artistas.", "A distribuição universal de livros pela imprensa.", "A existência de um único estilo em toda a Europa."], "Uma técnica visual pode ser evidência de escolhas artísticas e intelectuais. Não demonstra, sozinha, transformações universais em religião, acesso ou organização social."],
 ["Que pesquisa testa melhor a afirmação de que todos tiveram o mesmo acesso aos novos textos?", "Comparar circulação, custo e alfabetização entre grupos sociais e regiões.", ["Contar apenas quantos livros famosos sobreviveram.", "Usar um retrato de um leitor rico como prova de leitura universal.", "Supor igualdade de acesso porque a prensa foi inventada.", "Consultar somente o título de uma obra sem investigar leitores."], "Acesso é uma questão social e material. Custos, distribuição e capacidade de leitura variam entre grupos; exemplares famosos não representam toda a população."],
 ["Qual leitura reconhece mudança e continuidade simultâneas?", "Novas referências e técnicas se desenvolveram em sociedades que mantinham instituições e conflitos anteriores.", ["Toda mudança cultural implica desaparecimento instantâneo da sociedade anterior.", "A continuidade de poderes comprova ausência de inovação artística.", "O interesse clássico impede qualquer criação original.", "A circulação impressa elimina a necessidade de interpretar fontes."], "Mudanças históricas não substituem necessariamente todos os elementos anteriores. Relações entre inovação, instituições e conflitos precisam ser consideradas em conjunto."],
]);
add("Reformas religiosas e poder político", "As reformas religiosas do século XVI questionaram práticas e autoridades da Igreja ocidental e deram origem a diferentes correntes. A circulação de escritos e o apoio de governantes contribuíram para a expansão de propostas. Disputas religiosas também se relacionaram a interesses políticos; a reação católica combinou reafirmação doutrinária e reformas internas, não desaparecimento da instituição.", [
 ["Que relação entre religião e política é coerente com a síntese?", "Governantes e grupos sociais podiam apoiar correntes religiosas em disputas também relacionadas ao poder.", ["As reformas foram exclusivamente debates privados sem efeito político.", "Todos os governantes apoiaram uma única proposta da mesma maneira.", "O apoio político tornou irrelevante qualquer discussão doutrinária.", "A circulação impressa impediu a existência de correntes diferentes."], "Debates religiosos tinham conteúdo próprio e podiam articular-se a interesses de autoridades e grupos. Reconhecer a relação não reduz toda motivação à política nem exige uniformidade."],
 ["Como a circulação de escritos alterava as condições do debate?", "Ampliava acesso a argumentos e controvérsias, ainda sujeito a acesso desigual e mecanismos de controle.", ["Garantia a mesma interpretação a todos os leitores.", "Eliminava a necessidade de alfabetização.", "Impossibilitava censura porque qualquer texto era impresso.", "Tornava todas as correntes religiosas idênticas."], "Reprodução e circulação favorecem difusão de ideias, mas leitores, autoridades e condições de acesso influenciam recepção e controle. Tecnologia não determina concordância universal."],
 ["Qual comparação evita tratar a reação católica como mera imobilidade?", "Houve reafirmação de princípios e mudanças em práticas e organização interna.", ["A reação eliminou toda doutrina católica.", "Reafirmar princípios significa ausência de qualquer reforma interna.", "Toda mudança interna equivale a adotar a mesma corrente protestante.", "A existência da reação comprova desaparecimento imediato da Igreja."], "Mudança e continuidade podem coexistir. Reafirmação doutrinária não exclui respostas organizacionais e disciplinares, nem implica abandono de identidade religiosa."],
 ["Ao analisar um escrito de controvérsia religiosa, que cuidado é necessário?", "Identificar autor, destinatários e finalidade, distinguindo acusação polêmica de descrição neutra.", ["Considerar toda acusação uma prova independente de verificação.", "Tratar o texto como visão idêntica de todas as correntes.", "Ignorar seu período porque doutrinas nunca mudam.", "Usar somente o número de páginas como medida de verdade."], "Textos de disputa procuram persuadir e deslegitimar adversários. Sua interpretação exige contexto e confronto com outras fontes; relevância histórica não significa neutralidade."],
 ["Qual afirmação simplifica inadequadamente a multiplicidade de reformas?", "Todas as propostas tinham a mesma doutrina e a mesma relação com governos locais.", ["Correntes distintas podiam apresentar divergências entre si.", "A circulação de ideias influenciou o alcance dos debates.", "Interesses políticos podiam articular-se a questões religiosas.", "A Igreja católica organizou respostas às contestações."], "A síntese apresenta pluralidade. Reduzir propostas distintas a uma doutrina e relação política únicas elimina diferenças importantes do processo histórico."],
]);
add("Expansão marítima e redes atlânticas", "A expansão marítima europeia articulou técnicas de navegação, interesses comerciais, ação de monarquias e disputas por rotas. A chegada a territórios já habitados produziu conquista, trocas e violência, com efeitos distintos sobre grupos europeus, africanos e americanos. Chamar esses territórios de vazios apaga populações e relações existentes antes da conquista.", [
 ["Qual explicação articula fatores sem reduzir a expansão a uma única invenção?", "Técnicas, interesses econômicos e poderes políticos combinaram-se em condições históricas específicas.", ["A existência de instrumentos de navegação bastou para eliminar todos os obstáculos.", "As rotas foram abertas sem participação de autoridades políticas.", "A expansão não tinha relação com comércio ou disputas de poder.", "Todo contato teve os mesmos efeitos para conquistadores e conquistados."], "Mudanças técnicas oferecem possibilidades, mas seu uso depende de interesses, financiamento e disputas. A síntese apresenta combinação de condições, não determinismo tecnológico."],
 ["Qual problema histórico existe em descrever os territórios americanos como vazios?", "A formulação invisibiliza populações, usos do espaço e organizações anteriores à conquista.", ["Ela reconhece a diversidade dos povos que já habitavam os territórios.", "Ela comprova que todos os grupos receberam igualmente os conquistadores.", "Ela descreve apenas a ausência de qualquer relevo físico.", "Ela permite dispensar investigação sobre sociedades americanas."], "A ocupação anterior é parte central da história dos contatos e conflitos. A categoria vazio pode legitimar conquista ao apagar habitantes e relações territoriais existentes."],
 ["Um mapa europeu de rotas descreve automaticamente a experiência de todos os povos envolvidos?", "Não; revela um recorte de circulação e conhecimento que deve ser comparado a outras perspectivas.", ["Sim, pois mapas incluem necessariamente todos os usos sociais do território.", "Sim, porque a origem europeia garante neutralidade universal.", "Não, porque mapas não possuem qualquer valor como fonte histórica.", "Sim, se o mapa apresenta nomes de portos e oceanos."], "Mapas são fontes relevantes, mas fazem escolhas e refletem finalidades e saberes. Seus elementos não equivalem à experiência completa dos diferentes povos."],
 ["Qual relação pode coexistir no processo de contato sem contradição lógica?", "Trocas de produtos e conhecimentos podem ocorrer junto a conquista e violência.", ["A existência de troca prova ausência de coerção.", "A presença de violência impede toda circulação cultural.", "Toda circulação de conhecimento implica igualdade de poder.", "Contatos comerciais eliminam disputas por rotas."], "Processos de contato podem combinar relações diferentes. Troca não garante igualdade, e violência não impede circulação de bens, práticas ou conhecimentos."],
 ["Que pesquisa amplia o estudo para além da perspectiva das rotas europeias?", "Examinar ocupações locais, redes africanas e americanas e efeitos das conquistas sobre diferentes grupos.", ["Usar apenas registros de navegação de um único comandante.", "Pressupor que a chegada europeia foi o início de toda história local.", "Contar navios sem investigar relações com populações.", "Excluir relatos de grupos conquistados porque apresentam outra perspectiva."], "Ampliar as perspectivas permite contextualizar contatos e assimetrias. A história dos territórios e grupos não se inicia necessariamente com sua inclusão em mapas europeus."],
]);
add("Economia açucareira e trabalho", "A produção de açúcar na América portuguesa articulava grandes unidades de cultivo e processamento, circulação atlântica e trabalho escravizado. O destino externo de parte expressiva da produção influenciava investimentos e dependência comercial. Outras atividades abasteciam moradores e unidades produtivas; economia exportadora não significa inexistência de mercados internos.", [
 ["Qual análise relaciona produção exportadora e organização social?", "Grandes unidades, coerção do trabalho e redes comerciais compunham relações econômicas e de poder.", ["A exportação garantia igualdade entre proprietários e trabalhadores.", "O cultivo era realizado somente por empregados livres com direitos atuais.", "A produção dispensava processamento e transporte.", "O destino externo eliminava qualquer vínculo com poder local."], "Produção, trabalho e circulação não são dimensões isoladas. O trabalho escravizado e o controle das unidades articulavam interesses e hierarquias, não relações igualitárias."],
 ["Que continuidade econômica pode coexistir com o destaque do açúcar?", "Atividades de abastecimento e trocas internas ligadas às necessidades locais.", ["Ausência total de produção de alimentos para moradores.", "Proibição de qualquer atividade diferente da fabricação de açúcar.", "Desaparecimento de transportes internos porque havia exportação.", "Participação igual de todas as regiões na mesma unidade produtiva."], "A exportação exige abastecimento e transporte e convive com necessidades sociais locais. Um setor dominante não representa sozinho todas as atividades econômicas."],
 ["Por que um registro de produção de um proprietário não descreve integralmente a experiência dos trabalhadores?", "Seu foco e posição social podem omitir coerção, cotidiano e formas de resistência.", ["Todo registro contábil é obrigatoriamente falso e inútil.", "A quantidade produzida revela automaticamente direitos e condições de cada pessoa.", "Um proprietário representa a voz de todos os grupos de forma neutra.", "A existência de contas comprova ausência de trabalho coercitivo."], "Registros contábeis informam aspectos da produção, mas não abrangem todas as experiências. É preciso confrontá-los com fontes de outras posições e com o contexto das relações de trabalho."],
 ["Qual diferença distingue escravidão de uma relação assalariada livre?", "Coerção e condição jurídica de propriedade sobre pessoas, com restrições fundamentais à autonomia.", ["Somente o tamanho da unidade produtiva, pois direitos eram os mesmos.", "A existência de transporte marítimo, ausente em qualquer trabalho livre.", "A quantidade de açúcar produzida por mês, independentemente da condição das pessoas.", "O uso de ferramentas agrícolas, exclusivas do trabalho escravizado."], "A distinção central é social e jurídica, envolvendo coerção e restrição de liberdade. Tecnologia, escala ou volume de produção não definem isoladamente a condição do trabalhador."],
 ["Qual afirmação reconhece agência dos grupos escravizados sem minimizar a violência?", "Resistências e negociações podiam existir dentro de relações fortemente coercitivas.", ["A existência de resistência prova que a escravidão era voluntária.", "Coerção significa ausência absoluta de ações e estratégias dos escravizados.", "Negociações eliminavam automaticamente a condição jurídica de escravidão.", "Toda resistência assumia forma idêntica em qualquer local."], "Reconhecer ações e estratégias não transforma a relação em livre. Resistência pode assumir formas diversas sob coerção; violência e agência não são conceitos mutuamente excludentes."],
]);
add("Mineração, fiscalidade e interiorização", "A mineração na América portuguesa ampliou fluxos de pessoas, mercadorias e recursos para áreas do interior. A Coroa estabeleceu mecanismos de tributação e fiscalização; cobranças e controles produziram conflitos. A extração coexistiu com abastecimento, agricultura e comércio, e seus efeitos não podem ser medidos apenas pela quantidade de metal enviada à metrópole.", [
 ["Qual relação integra mineração e reorganização do território?", "Fluxos para o interior estimularam caminhos, núcleos urbanos e redes de abastecimento.", ["A mineração manteve toda circulação restrita às áreas litorâneas açucareiras.", "A extração eliminou a necessidade de alimentos e transportes.", "Toda população colonial passou a exercer a mesma atividade.", "A presença de minérios impediu o surgimento de núcleos urbanos."], "A concentração de atividade extrativa atrai pessoas e cria demanda por circulação e abastecimento. Esses vínculos articulam interior e outras regiões, não isolamento completo."],
 ["Por que fiscalidade pode ser fonte de conflito, além de fonte de receita?", "Cobrança e fiscalização distribuem custos e ampliam controles sobre produtores e comerciantes.", ["Qualquer imposto torna impossível a atividade econômica.", "Os tributos eram pagos igualmente por todos, sem qualquer disputa.", "Fiscalização não possui relação com autoridade política.", "A arrecadação elimina diferenças de interesse entre Coroa e grupos locais."], "Tributos envolvem interesses e relações de poder. Conflitos podem surgir de valores, métodos de cobrança e controle, sem que toda tributação extinga automaticamente a produção."],
 ["Que informação complementa um registro de metal exportado para estudar efeitos locais?", "Dados sobre abastecimento, circulação de pessoas, preços e condições de trabalho.", ["Somente a cor das moedas cunhadas na metrópole.", "Uma soma do metal sem localização ou período.", "O total exportado tomado como medida direta do bem-estar de todos.", "A exclusão das atividades não extrativas dos registros de pesquisa."], "Os efeitos locais incluem vida material, trabalho e redes comerciais. Exportação é um indicador parcial; outras atividades e condições são necessárias à análise social."],
 ["Qual interpretação evita reduzir conflitos fiscais a uma unidade de interesses de todos os moradores?", "Grupos locais podiam ter posições diferentes conforme seu papel na produção, circulação e administração.", ["Todos os moradores eram proprietários de minas com os mesmos interesses.", "A ação da Coroa tornava toda população igualmente beneficiada.", "A presença de conflito eliminava diferenças entre grupos locais.", "Tributos só afetavam pessoas fora do território colonial."], "A sociedade tinha posições diversas, inclusive dentro das regiões mineradoras. Um conflito não transforma moradores em um grupo homogêneo de interesses."],
 ["Que continuidade impede afirmar que a mineração substituiu toda economia anterior?", "Produção de alimentos, comércio e outros setores persistiram e se articularam à extração.", ["O envio de metal significou desaparecimento automático do açúcar.", "A interiorização eliminou toda relação com o litoral.", "A mineração tornou desnecessário trabalho em qualquer outra atividade.", "A tributação passou a incidir apenas sobre uma sociedade sem trocas."], "Setores econômicos podem coexistir e relacionar-se. O destaque de uma atividade em um período não comprova extinção completa das demais."],
]);
add("Iluminismo e limites das mudanças", "Pensadores iluministas discutiram razão, direitos e limites do poder, com propostas e posições distintas. Ideias de liberdade podiam inspirar críticas ao absolutismo, mas sua aplicação não foi igual para todos os grupos. Em diferentes processos revolucionários, declarações de direitos coexistiram com exclusões políticas, coloniais e sociais.", [
 ["Qual análise explica a coexistência entre discurso de direitos e exclusões?", "Ideais declarados e formas concretas de aplicação podiam divergir segundo grupos e instituições.", ["Qualquer declaração de direitos eliminou imediatamente todas as desigualdades.", "Exclusões provam que ninguém discutiu liberdade no período.", "Todos os iluministas apresentaram uma proposta única e idêntica.", "A crítica ao absolutismo implica ausência de disputa política."], "Ideias influenciam ações, mas não determinam aplicação igualitária imediata. Comparar princípios e práticas revela limites, contradições e disputas das transformações."],
 ["Que crítica ao poder é compatível com a discussão iluminista sintetizada?", "Questionar autoridade sem limites e discutir justificações e controles do governo.", ["Defender que toda autoridade se dispensa de justificativa por ser hereditária.", "Considerar a razão incompatível com debate público.", "Afirmar que direitos pertencem necessariamente a um único governante.", "Eliminar qualquer distinção entre poder e vontade pessoal do soberano."], "Discussões sobre direitos e limites envolvem fundamentos da autoridade. Não correspondem à aceitação automática de poder pessoal ilimitado, embora propostas históricas fossem diversas."],
 ["Como investigar quem foi efetivamente incluído por uma declaração de direitos?", "Comparar seu texto com regras de cidadania e práticas de participação dos diferentes grupos.", ["Supor inclusão universal a partir apenas da palavra direitos.", "Consultar somente o retrato de um governante.", "Ignorar regulamentações posteriores porque uma declaração é suficiente.", "Aplicar a todos os grupos a experiência de um único proprietário."], "A abrangência jurídica e efetiva depende de regras e práticas. Palavras gerais não comprovam acesso universal a voto, liberdade ou participação."],
 ["Qual relação evita tratar ideias como causa suficiente de uma revolução?", "Articular debates intelectuais a conflitos sociais, condições econômicas e disputas políticas.", ["Explicar todo evento apenas pela publicação de um livro.", "Excluir interesses econômicos porque havia discussões de direitos.", "Considerar que pensar liberdade torna automática qualquer mudança de governo.", "Tratar todas as revoluções como aplicação idêntica de uma proposta."], "Transformações têm múltiplas condições. Ideias podem oferecer linguagem e objetivos a movimentos, mas sua ação depende de grupos, recursos e conflitos concretos."],
 ["Que comparação com o presente preserva o caráter histórico de direitos?", "Examinar mudanças em definição, abrangência e mecanismos de garantia ao longo do tempo.", ["Presumir que o uso da mesma palavra significa direitos idênticos em qualquer época.", "Considerar todo direito atual existente de forma completa desde o primeiro debate.", "Tomar a exclusão antiga como prova de impossibilidade de mudança futura.", "Ignorar disputas porque conceitos jurídicos não se transformam."], "Direitos são formulados, disputados e aplicados em contextos. Continuidade de palavras não garante igualdade de alcance, titularidade ou proteção em períodos diferentes."],
]);
add("Industrialização e organização do trabalho", "Uma síntese sobre a industrialização distingue produção em oficinas e produção fabril. Máquinas, concentração de trabalhadores e disciplina de horários ampliaram certas capacidades produtivas, enquanto jornadas, salários e condições de trabalho se tornaram objeto de conflito. O aumento da produção não significou distribuição automática e igual dos benefícios.", [
 ["Qual relação explica o conflito social apesar do aumento da produção?", "Ganhos produtivos podiam coexistir com jornadas extensas e distribuição desigual de renda.", ["Produzir mais assegura automaticamente salários iguais e jornadas menores.", "A existência de máquinas elimina qualquer trabalho humano.", "Conflito trabalhista demonstra que nenhuma capacidade produtiva cresceu.", "O regime fabril reproduz necessariamente toda autonomia da oficina."], "Produtividade e condições sociais são dimensões relacionadas, mas distintas. O crescimento não determina, por si só, a distribuição dos ganhos nem as jornadas."],
 ["Uma fábrica exige presença em horários fixos e coordena tarefas sucessivas. Qual mudança isso evidencia em relação ao controle do tempo de trabalho?", "Maior coordenação e disciplina do ritmo produtivo sob a organização fabril.", ["Eliminação de qualquer fiscalização do tempo.", "Autonomia idêntica de cada trabalhador para interromper toda produção.", "Ausência de divisão de tarefas porque existem máquinas.", "Retorno automático a produção exclusivamente familiar."], "Máquinas e tarefas interdependentes favorecem coordenação central do tempo e disciplina. Isso pode reduzir autonomia sobre ritmo e horário em comparação com certas formas de oficina."],
 ["Um registro de produção elevada basta para comprovar melhoria das condições dos trabalhadores?", "Não; salários, jornada, segurança e distribuição dos ganhos precisam ser examinados.", ["Sim, pois produtividade equivale a bem-estar em qualquer sociedade.", "Sim, desde que o proprietário comemore o resultado.", "Não, porque registros produtivos nunca oferecem informação histórica.", "Sim, porque máquinas impedem acidentes por definição."], "Registros produtivos têm valor, mas seu indicador não abrange toda experiência do trabalho. É preciso estudar condições materiais e sociais para avaliar benefícios e custos."],
 ["Qual ação coletiva se relaciona à disputa sobre condições de trabalho?", "Organização de trabalhadores para reivindicar mudanças de jornada, remuneração e proteção.", ["Aceitação obrigatória e uniforme de toda regra fabril.", "Desaparecimento de qualquer negociação com empregadores.", "Extinção da produção urbana como condição de toda reivindicação.", "Proibição de discutir salários por haver aumento de produção."], "Conflitos sobre tempo, renda e condições podem gerar organização coletiva. Isso não exige abandono de toda produção nem implica aceitação uniforme das regras."],
 ["Que comparação evita explicar industrialização somente por invenções técnicas?", "Relacionar máquinas a mercados, investimentos, trabalho, energia e instituições.", ["Considerar a presença de uma máquina suficiente para caracterizar toda sociedade industrial.", "Ignorar oferta de energia e circulação de mercadorias.", "Atribuir todas as mudanças sociais a um único inventor.", "Usar apenas o número de ferramentas para definir direitos e salários."], "Técnicas operam em condições sociais e econômicas. Sua difusão e efeitos dependem de trabalho, recursos, mercados e formas de organização, não apenas da invenção."],
]);
add("Revolução Francesa e cidadania", "A Revolução Francesa questionou privilégios e autoridade do Antigo Regime. Declarações de liberdade e igualdade, mudanças institucionais e disputas entre grupos marcaram o processo. A cidadania não foi ampliada de forma estável e uniforme para todos; diferenças de gênero, propriedade e condição colonial permaneceram em debate e conflito.", [
 ["Qual leitura compara ideais revolucionários e sua aplicação sem confundi-los?", "A afirmação de igualdade abriu disputas sobre sua abrangência, sem eliminar imediatamente todas as exclusões.", ["A declaração de igualdade assegurou de imediato voto universal estável a toda população.", "Exclusões significam que a crítica aos privilégios nunca existiu.", "Todas as fases revolucionárias tinham a mesma organização de poder.", "A condição colonial era independente de qualquer debate de liberdade."], "Princípios e práticas podem divergir. Direitos foram objeto de disputa e variação; a existência de ideais não comprova inclusão universal imediata."],
 ["Uma crítica a privilégios hereditários atinge qual característica do Antigo Regime?", "A diferenciação de direitos e posições por ordens e nascimento.", ["A igualdade jurídica universal já plenamente aplicada a todos.", "A ausência de qualquer hierarquia social.", "A eleição de todos os cargos por sufrágio universal.", "A distribuição uniforme de impostos entre todos os grupos."], "Privilégios associados a ordens e nascimento constituíam hierarquias jurídicas e sociais. Questioná-los não é o mesmo que confirmar igualdade preexistente."],
 ["Como avaliar se a igualdade proclamada alcançou mulheres em determinado momento?", "Comparar participação política e regras de cidadania com o princípio declarado.", ["Presumir igualdade de participação porque um texto usa a palavra cidadãos.", "Consultar apenas a quantidade de bandeiras em uma manifestação.", "Aplicar a todas as pessoas a experiência de um líder masculino.", "Desconsiderar normas de participação porque discursos substituem instituições."], "Acesso efetivo deve ser investigado por regras e práticas. Um princípio geral precisa ser confrontado com a titularidade dos direitos e as condições de exercício."],
 ["Qual informação enfraquece a leitura de que a Revolução foi um bloco de ideias e práticas imutáveis?", "A existência de fases, instituições e grupos com projetos concorrentes.", ["O uso de símbolos em manifestações.", "A presença de textos escritos no período.", "O fato de mudanças terem ocorrido na França.", "A circulação de notícias sobre conflitos em outros países."], "Diversidade de fases e projetos demonstra transformações internas. Localização e uso de símbolos não bastam para caracterizar unidade ou multiplicidade dos projetos."],
 ["Que relação conecta condição colonial e debates revolucionários?", "A escravidão e o domínio colonial colocavam à prova o alcance dos ideais de liberdade.", ["A liberdade proclamada tornava qualquer relação colonial automaticamente livre.", "A escravidão era compatível com igualdade jurídica universal sem tensão.", "A condição das colônias não podia ser discutida por nenhum grupo.", "Um ideal político elimina por si só as relações de coerção existentes."], "Princípios de liberdade podiam ser mobilizados contra coerção e hierarquias coloniais. Sua aplicação dependia de conflitos e decisões, não de efeito automático do discurso."],
]);
add("Independências nas Américas", "A crise de autoridades metropolitanas e conflitos locais contribuíram para independências em diferentes partes das Américas. Projetos de governo, território e cidadania divergiam entre elites e outros grupos. A ruptura política com uma metrópole podia preservar desigualdades de propriedade e formas de coerção do trabalho; processos distintos não produziram resultados sociais idênticos.", [
 ["Qual distinção é necessária entre independência política e transformação social?", "Romper o vínculo metropolitano não implica eliminar automaticamente desigualdades internas.", ["Toda independência extingue imediatamente a concentração de terras.", "Manter desigualdades significa ausência de qualquer ruptura política.", "A mudança de governo torna todos os projetos de cidadania idênticos.", "A crise metropolitana elimina a participação de grupos locais."], "Soberania e relações sociais são dimensões distintas. Rupturas políticas podem coexistir com continuidades de propriedade, trabalho e hierarquia."],
 ["Por que diferenças entre projetos de território e governo são relevantes?", "Porque a saída do domínio metropolitano podia gerar disputas sobre como organizar o novo poder.", ["Porque todos os grupos desejavam necessariamente a mesma forma de Estado.", "Porque independência impede qualquer conflito posterior.", "Porque limites territoriais são definidos apenas por relevo natural.", "Porque projetos políticos não influenciam instituições."], "O fim de uma autoridade comum não define automaticamente novas instituições ou fronteiras. Interesses e projetos concorrentes podem produzir disputas de organização."],
 ["Um discurso de uma elite independentista pode ser usado de que modo?", "Como expressão de um projeto, a ser confrontado com outras vozes e práticas.", ["Como prova de que todos os habitantes concordavam com o autor.", "Como registro sem interesses por apoiar a independência.", "Como substituto suficiente de toda análise das relações sociais.", "Como demonstração de que apenas elites participaram do processo."], "Discursos expressam posições e finalidades. Sua relevância não lhes confere representatividade universal nem prova ausência de ação de outros grupos."],
 ["Que continuidade pode ser investigada após a ruptura política?", "Permanência de concentração de propriedade e coerção do trabalho, segundo cada processo.", ["Permanência automática do mesmo vínculo jurídico metropolitano em toda independência.", "Ausência total de governo nos novos territórios.", "Igualdade social universal em todos os países independentes.", "Extinção de comércio com qualquer região estrangeira."], "A síntese distingue ruptura metropolitana e possíveis continuidades internas. As formas concretas variam e devem ser investigadas, sem generalização uniforme."],
 ["Qual procedimento permite comparar dois processos de independência sem apagar diferenças?", "Definir critérios comuns e examinar cronologia, grupos envolvidos, instituições e relações de trabalho.", ["Usar somente a palavra independência como prova de trajetórias idênticas.", "Comparar apenas as cores das bandeiras.", "Aplicar a cronologia de um caso ao outro sem consultar fontes.", "Ignorar condições locais porque ambas eram sociedades americanas."], "Critérios comuns permitem comparação; contexto e evidências preservam diferenças. Localização continental ou um rótulo político não tornam processos equivalentes."],
]);
add("Transferência da corte e mudanças coloniais", "A transferência da corte portuguesa para o Brasil em 1808 relacionou-se ao contexto europeu das guerras napoleônicas. A instalação da monarquia no Rio de Janeiro e medidas comerciais e administrativas alteraram relações entre metrópole e colônia. Em 1815, o Brasil foi elevado à condição de Reino Unido a Portugal e Algarves; a independência de 1822 não deve ser confundida com essas mudanças anteriores.", [
 ["Qual sequência distingue os três eventos apresentados?", "Transferência da corte em 1808, elevação a Reino Unido em 1815 e independência em 1822.", ["Independência em 1808, transferência em 1815 e Reino Unido em 1822.", "Reino Unido em 1808, independência em 1815 e transferência em 1822.", "Transferência e independência foram o mesmo ato em 1808.", "Independência precedeu a instalação da corte no Rio."], "Os marcos têm significados e datas diferentes. A presença da corte e a mudança de condição jurídica não equivalem, por si sós, à separação política de 1822."],
 ["Qual relação entre contexto externo e transformação interna é coerente?", "Uma crise europeia influenciou a transferência de instituições e mudanças administrativas no Brasil.", ["A transferência ocorreu sem relação com conflitos europeus.", "As guerras europeias definiram diretamente todos os resultados sociais posteriores.", "A corte veio apenas para celebrar uma independência já concluída.", "As instituições coloniais permaneceram sem qualquer alteração após a instalação."], "O contexto europeu ajuda a explicar a transferência, mas seus desdobramentos dependem também de ações e condições locais. Relação não é determinação integral de todo resultado."],
 ["Por que a instalação da corte alterava a posição do Rio de Janeiro?", "A cidade passou a sediar decisões e instituições da monarquia, com novas demandas e redes de poder.", ["A cidade se tornou uma capital republicana eleita por todos os habitantes.", "A presença da corte eliminou automaticamente hierarquias e escravidão.", "A cidade perdeu qualquer função administrativa.", "O governo passou a depender apenas de autoridades locais sem vínculo monárquico."], "Sediar a monarquia muda funções políticas e administrativas e gera demandas materiais. Isso não significa republicanização ou igualdade social automática."],
 ["Qual interpretação da elevação de 1815 é inadequada?", "Ela já constituía a mesma ruptura soberana realizada em 1822.", ["Ela alterava a condição jurídica do Brasil dentro da monarquia.", "Ela aconteceu depois da transferência da corte.", "Ela não deve ser confundida com independência política.", "Ela integra mudanças nas relações entre os territórios da monarquia."], "Reino Unido mantinha articulação com Portugal e a monarquia. A independência é um marco posterior de separação política, com outro significado."],
 ["Que evidência complementa decretos administrativos para avaliar os efeitos da instalação da corte?", "Registros de preços, moradia, trabalho e experiências de diferentes grupos urbanos.", ["Somente a assinatura do governante em um decreto.", "Um retrato da corte tratado como medida do bem-estar de todos.", "O número de títulos nobiliárquicos tomado como prova de igualdade.", "A data da chegada usada como explicação de toda experiência social."], "Normas e instituições não abrangem toda vivência da população. Fontes sobre condições materiais e grupos diferentes permitem relacionar decisão política e efeitos sociais."],
]);
add("Independência do Brasil e continuidades", "A independência de 1822 rompeu vínculos políticos com Portugal e manteve uma monarquia no Brasil. Sua organização envolveu disputas regionais e diferentes participações sociais. A escravidão e a concentração de propriedade persistiram. A Constituição de 1824 estabeleceu instituições do Império e regras de participação que não equivaliam ao sufrágio universal contemporâneo.", [
 ["Qual análise identifica simultaneamente ruptura e continuidade?", "Separação política de Portugal com preservação de monarquia, escravidão e hierarquias de propriedade.", ["Extinção de escravidão e monarquia no mesmo ato de independência.", "Ausência de qualquer mudança porque continuou a concentração de propriedade.", "Implantação imediata de uma república com sufrágio universal.", "Manutenção integral do vínculo político colonial sem novo Estado."], "A ruptura de soberania pode coexistir com instituições e relações sociais mantidas. Não se deve confundir independência, república e abolição, que têm processos distintos."],
 ["Que investigação é necessária para avaliar participação política no início do Império?", "Examinar regras de cidadania e representação e quem efetivamente podia exercê-las.", ["Presumir participação universal porque o país era independente.", "Usar somente o número de habitantes para contar eleitores.", "Tratar toda pessoa residente como elegível aos mesmos cargos.", "Aplicar as regras constitucionais atuais diretamente a 1824."], "Independência não define por si só abrangência de cidadania. Regras históricas e práticas permitem estudar condições de participação sem anacronismo."],
 ["Qual informação contraria a ideia de consenso nacional completo no processo?", "A existência de disputas regionais e de projetos distintos entre grupos.", ["A presença de uma capital administrativa.", "O uso de documentos escritos pela monarquia.", "A existência de um território com litoral.", "A produção de símbolos públicos de independência."], "Conflitos e projetos concorrentes demonstram que a separação não foi experimentada como um acordo uniforme. Símbolos ou instituições não comprovam consenso completo."],
 ["Um relato que menciona apenas líderes políticos é suficiente para negar participação popular?", "Não; o recorte do relato pode omitir atuações de outros grupos e exige confronto com outras fontes.", ["Sim, porque ausência em um relato é prova definitiva de ausência histórica.", "Sim, desde que o autor tenha vivido no período.", "Não, porque todo relato de líder é obrigatoriamente falso.", "Sim, porque independências só podem envolver titulares de cargos."], "Silêncio de uma fonte não equivale à inexistência de um grupo. Confrontar perspectivas e vestígios permite investigar participações além do recorte do autor."],
 ["Qual cronologia evita fundir diferentes transformações da história brasileira?", "Independência em 1822, abolição em 1888 e proclamação da República em 1889.", ["República em 1822, abolição em 1824 e independência em 1889.", "Abolição e República ocorreram juntas na independência de 1822.", "Abolição em 1889 e República em 1888, antes da independência.", "A Constituição de 1824 extinguiu a escravidão e proclamou a República."], "São marcos diferentes, com agentes, disputas e efeitos próprios. A sequência 1822, 1888 e 1889 ajuda a distinguir soberania, relações de trabalho e forma de governo."],
]);
add("Abolição e cidadania no pós-emancipação", "A abolição legal da escravidão no Brasil, em 1888, resultou de processos que envolveram ação de pessoas escravizadas, movimentos abolicionistas, conflitos e decisões políticas. O fim da condição jurídica de escravidão não assegurou automaticamente acesso igual à terra, renda ou proteção social. Disputas por cidadania continuaram após a emancipação.", [
 ["Qual distinção explica a continuidade das lutas após 1888?", "Liberdade jurídica e acesso efetivo a recursos e direitos são dimensões relacionadas, mas não idênticas.", ["A liberdade jurídica distribuiu imediatamente terras e renda de maneira igual.", "A permanência de desigualdade comprova que a escravidão nunca foi abolida legalmente.", "A emancipação eliminou qualquer conflito sobre cidadania.", "A alteração legal não teve importância para a condição das pessoas."], "O marco legal muda a condição de escravidão, mas não resolve automaticamente condições materiais ou discriminação. Reconhecer seus limites não elimina a importância da ruptura jurídica."],
 ["Qual interpretação evita reduzir a abolição a uma concessão isolada de uma autoridade?", "Considerar pressões, resistências e mobilizações de diferentes grupos no processo.", ["Descrever pessoas escravizadas como incapazes de participar de qualquer resistência.", "Atribuir todo o processo exclusivamente ao momento da assinatura da lei.", "Ignorar movimentos sociais por existir decisão parlamentar.", "Presumir consenso completo entre proprietários e trabalhadores."], "A decisão legal integra um processo de disputas e ações. Diferentes grupos, inclusive pessoas escravizadas, participaram de pressões e resistências que precisam ser investigadas."],
 ["Que fonte ajuda a estudar experiência social após a abolição além da lei?", "Registros de trabalho, associações, moradia e relatos de pessoas emancipadas.", ["Somente uma reprodução da assinatura da lei.", "Um retrato de autoridade tomado como descrição da renda dos libertos.", "A data de 1888 usada como prova de igualdade de oportunidades.", "O nome de uma cidade usado como substituto de condições de vida."], "A lei define uma alteração jurídica. Experiências posteriores exigem fontes sobre vida, recursos, vínculos e ações dos grupos, não apenas o texto normativo."],
 ["Qual relação entre continuidade e mudança é coerente?", "O fim da escravidão pode coexistir com persistência de desigualdades e desenvolvimento de novas estratégias de participação.", ["Qualquer desigualdade posterior significa ausência de toda mudança.", "Toda estratégia de participação se encerrou com a emancipação.", "A mudança jurídica torna irrelevante qualquer investigação das condições materiais.", "A cidadania passou a depender apenas da ausência de trabalho."], "Transformação jurídica e permanências sociais não se excluem. Grupos podem formular novas reivindicações e estratégias em condições alteradas pela emancipação."],
 ["Qual conclusão não pode ser obtida apenas da data de uma lei?", "O grau de acesso à terra, renda e proteção social de todas as pessoas emancipadas.", ["A localização temporal do marco jurídico.", "A distinção cronológica entre 1888 e a República de 1889.", "A ocorrência de uma decisão legal no período.", "A necessidade de investigar efeitos posteriores."], "Uma data permite localizar o evento, mas não descreve a abrangência das condições de vida. A avaliação material e social exige outras evidências e recortes."],
]);
add("Primeira República e participação política", "A proclamação da República em 1889 mudou a forma de governo, mas a participação política continuou limitada por regras de acesso e práticas de poder. Em muitas regiões, redes locais controlavam recursos e pressionavam eleitores; mecanismos formais coexistiam com coerção e disputas. Mudança institucional e democratização efetiva não são equivalentes automáticos.", [
 ["Qual comparação distingue forma de governo e efetividade da participação?", "A existência de instituições republicanas não garante, por si só, participação livre e ampla.", ["A proclamação estabeleceu imediatamente as mesmas regras de voto atuais.", "Toda república dispensa eleições e representação.", "Pressão sobre eleitores comprova ausência de qualquer instituição formal.", "A mudança de monarquia para república elimina relações locais de poder."], "Instituições e práticas podem divergir. A forma republicana precisa ser estudada junto a regras de acesso, liberdade do eleitor e relações de poder."],
 ["Como controle de recursos pode se relacionar a coerção eleitoral?", "Dependência material pode ser usada por autoridades locais para pressionar escolhas políticas.", ["A dependência garante que toda escolha seja espontânea e independente.", "Recursos materiais não podem ter qualquer relação com participação política.", "A coerção só existe quando não há candidatos.", "Pressão eleitoral distribui necessariamente recursos de modo igualitário."], "Relações de dependência podem influenciar a liberdade de escolha. A existência de voto formal não comprova autonomia em contextos de pressão social ou material."],
 ["Um registro oficial de votos prova sozinho a liberdade de todos os votantes?", "Não; é necessário investigar condições de votação, acesso e pressões.", ["Sim, porque contagem formal registra todas as experiências dos eleitores.", "Sim, se o vencedor recebeu grande número de votos.", "Não, porque documentos oficiais não têm qualquer valor histórico.", "Sim, porque a palavra república elimina a possibilidade de coerção."], "Registros de votação são fontes importantes, mas não revelam automaticamente coerção ou exclusão. Outras evidências contextualizam como os resultados foram produzidos."],
 ["Que mudança pode coexistir com práticas locais persistentes?", "Instituições nacionais republicanas podem funcionar em uma sociedade com redes de poder herdadas ou reorganizadas.", ["Instituições novas extinguem instantaneamente toda relação social anterior.", "Poder local impede a existência de qualquer governo nacional.", "Continuidade de redes locais significa que a forma de governo permaneceu monárquica.", "A República exige igualdade econômica já completa antes de funcionar."], "Mudanças de regime não substituem automaticamente todos os vínculos sociais. Poderes locais e instituições nacionais podem articular-se sob a nova forma de governo."],
 ["Qual pesquisa avalia melhor democratização do que apenas a troca de regime?", "Comparar abrangência do voto, competição, liberdade de escolha e acesso à representação.", ["Verificar somente se o governante usa título republicano.", "Contar o número de bandeiras em uma cerimônia oficial.", "Usar apenas a data de proclamação como medida de participação.", "Comparar os nomes dos prédios sem estudar eleitores e práticas."], "Democratização envolve quem participa e em quais condições. Títulos, símbolos e datas não substituem investigação da liberdade e abrangência política."],
]);
add("Primeira Guerra e múltiplas causas", "A Primeira Guerra Mundial começou em 1914 em um cenário de rivalidades imperialistas, nacionalismos, alianças e corrida armamentista. Um atentado funcionou como estopim, mas não explica sozinho a expansão do conflito. Mobilização de recursos, trincheiras e impactos sobre civis mostraram relações entre decisões políticas, tecnologia e organização das sociedades.", [
 ["Que distinção explica por que o estopim não é causa suficiente de toda a guerra?", "O atentado desencadeou uma crise em estruturas prévias de rivalidade e alianças.", ["O atentado criou do zero todas as rivalidades e armamentos.", "A existência de alianças tornou impossível ampliar o conflito.", "Nacionalismos só surgiram após o término da guerra.", "A corrida armamentista impedia decisões políticas de mobilização."], "É necessário distinguir evento desencadeador e condições acumuladas. Rivalidades, alianças e armamentos ajudam a explicar como uma crise se expandiu."],
 ["Qual relação entre alianças e ampliação da guerra é coerente?", "Compromissos e decisões de governos podiam envolver outros países em uma crise inicialmente localizada.", ["Uma aliança determina paz permanente independentemente dos interesses.", "Alianças eliminam a necessidade de decisões de mobilização.", "Todo país aliado tinha interesses internos e externos idênticos.", "A existência de alianças prova que conflitos coloniais eram irrelevantes."], "Alianças influenciam cálculos e compromissos, mas governos tomam decisões em contextos específicos. Não significam identidade de interesses nem paz obrigatória."],
 ["Um relato de soldado de trincheira permite qual uso histórico?", "Investigar experiência localizada da guerra, confrontando-a com outras fontes e recortes.", ["Reconstruir com certeza todos os acontecimentos de todas as frentes.", "Descrever automaticamente a experiência de todos os civis.", "Eliminar a necessidade de contexto por ser testemunho pessoal.", "Ignorar o testemunho porque fontes pessoais não informam experiências."], "Testemunhos oferecem acesso a experiências e perspectivas específicas. Sua abrangência é limitada; comparação e contexto não anulam seu valor, mas delimitam interpretações."],
 ["Que análise relaciona guerra e sociedade além do combate militar?", "Examinar produção, abastecimento, trabalho e efeitos sobre civis durante a mobilização.", ["Considerar apenas movimentos de tropas como toda a experiência social.", "Presumir que civis não eram afetados por conflitos entre exércitos.", "Separar completamente decisões de guerra de recursos econômicos.", "Tratar tecnologia como independente de produção e organização."], "Mobilização envolve recursos, trabalho e vida cotidiana. As sociedades são afetadas além das frentes; decisões militares dependem também de condições materiais."],
 ["Qual cronologia distingue as duas guerras mundiais sem confundir seus estopins?", "A Primeira começou em 1914; a Segunda, em 1939, em outro contexto de conflitos.", ["Ambas começaram em 1914 e tiveram o mesmo atentado como único motivo.", "A Segunda terminou antes do início da Primeira.", "A Primeira começou em 1939 e a Segunda em 1914.", "A Primeira foi uma fase de combate da Guerra Fria posterior."], "As guerras têm datas e condições próprias. Relações históricas entre os períodos não autorizam tratá-las como um evento único com causas idênticas."],
]);
add("Segunda Guerra, propaganda e perseguição", "A Segunda Guerra Mundial ocorreu entre 1939 e 1945 em um contexto que incluía expansionismo e regimes autoritários. Propaganda mobilizava populações e legitimava políticas, enquanto perseguições e genocídio atingiam grupos definidos por ideologias racistas. Analisar propaganda exige distinguir sua intenção persuasiva de evidências sobre o que ocorreu.", [
 ["Qual interpretação relaciona propaganda e poder sem tratá-la como fonte neutra?", "Ela podia legitimar políticas e construir imagens de aliados, inimigos e grupos perseguidos.", ["Toda propaganda registra os fatos sem seleção de informações.", "Mensagens persuasivas não têm relação com políticas de Estado.", "A repetição de uma mensagem comprova sua verdade histórica.", "A existência de propaganda torna desnecessário consultar outras fontes."], "Propaganda procura mobilizar e legitimar. Sua seleção de imagens e argumentos revela objetivos e ideologias, mas precisa ser confrontada com evidências de práticas e acontecimentos."],
 ["Que procedimento é adequado ao estudar uma mensagem racista produzida por um regime perseguidor?", "Analisar sua função de desumanização e legitimidade da violência, sem adotar sua classificação como descrição válida dos grupos.", ["Usar suas categorias como explicação científica da desigualdade entre pessoas.", "Considerar o texto prova de que todos os contemporâneos concordavam.", "Reproduzir a classificação como verdade sem contextualização.", "Eliminar outras fontes por divergirem da mensagem oficial."], "Estudar ideologia não significa endossá-la. Categorias racistas devem ser analisadas como instrumentos históricos de perseguição e poder, não como descrição científica das pessoas."],
 ["Por que testemunhos, documentos administrativos e vestígios devem ser confrontados?", "Eles oferecem recortes diferentes e podem sustentar conjuntamente a investigação de políticas e experiências.", ["A divergência de perspectivas torna impossível qualquer conhecimento histórico.", "Um único discurso oficial contém obrigatoriamente toda a experiência das vítimas.", "Vestígios materiais dispensam identificação de contexto e proveniência.", "Testemunhos pessoais são todos equivalentes, sem necessidade de exame."], "Confrontar fontes permite ampliar evidências e investigar diferenças entre políticas, registros e experiências. Contexto, proveniência e recorte continuam necessários."],
 ["Qual distinção entre regime autoritário e democracia é relevante ao contexto?", "Supressão de oposição e liberdades limita contestação e controle público das decisões.", ["Um regime autoritário caracteriza-se por participação universal livre em todos os cargos.", "Propaganda só pode existir em democracia e nunca em autoritarismo.", "A existência de governo basta para identificar ausência de qualquer liberdade.", "Controle público de decisões impede qualquer eleição democrática."], "A possibilidade de oposição, liberdades e controle das decisões distingue instituições e práticas. Não se identifica regime apenas pela presença de governo ou propaganda."],
 ["Qual afirmação evita relativizar genocídio como simples disputa de opiniões?", "Perseguição organizada e extermínio precisam ser investigados como ações e políticas, com evidências e responsabilidade histórica.", ["A intenção persuasiva da propaganda transforma extermínio em debate sem consequências.", "Toda fonte sobre violência possui o mesmo valor independentemente de evidências.", "A existência de conflito torna impossível reconhecer vítimas e responsabilidades.", "Ideologias racistas eram apenas escolhas estéticas sem relação com práticas."], "Genocídio não é uma opinião abstrata: envolve práticas, políticas e vítimas. Investigar evidências e responsabilidade não equivale a tratar propaganda e documentação como versões de mesmo valor."],
]);
add("Guerra Fria e ditaduras na América Latina", "Após a Segunda Guerra, a disputa entre Estados Unidos e União Soviética influenciou alianças, propaganda e conflitos em diferentes regiões. Na América Latina, governos autoritários relacionaram discursos de segurança a repressão e restrições de direitos. O contexto internacional não elimina a importância de interesses locais, ações de grupos sociais e processos próprios de cada país.", [
 ["Qual explicação evita reduzir todos os processos latino-americanos a decisões externas?", "Articular disputa internacional a interesses, instituições e conflitos locais.", ["A Guerra Fria determinou resultados idênticos em todos os países.", "Os grupos locais não tiveram qualquer ação ou interesse político.", "A existência de contexto internacional impede estudar conflitos internos.", "Todo regime regional foi uma cópia sem diferenças de um único modelo."], "Influências externas se relacionam a condições e decisões locais. A articulação permite investigar diferenças entre países, sem negar o contexto da disputa global."],
 ["Que tensão existe entre discurso de segurança e restrição de direitos?", "A justificativa de proteger a sociedade pode ser usada para legitimar repressão e reduzir contestação.", ["Invocar segurança garante automaticamente respeito a todas as liberdades.", "Restringir direitos elimina qualquer relação com exercício de poder.", "A ausência de oposição comprova consenso livre de toda população.", "O uso de discurso político impede a prática de violência estatal."], "Justificações oficiais devem ser confrontadas com práticas e efeitos. Silêncio ou ausência de oposição pública pode resultar de coerção, não de consenso livre."],
 ["Como examinar a afirmação de consenso em um período de censura?", "Investigar mecanismos de controle, manifestações impedidas e fontes que revelem vozes silenciadas.", ["Contar somente notícias autorizadas como retrato de todas as opiniões.", "Presumir concordância porque não há crítica na imprensa controlada.", "Excluir documentos de grupos opositores por não serem oficiais.", "Usar a ausência de protesto público como prova suficiente de liberdade."], "Censura modifica o que pode aparecer publicamente. Ausência de crítica em fontes controladas não é medida neutra de opiniões; investigar repressão e silêncios é essencial."],
 ["Qual relação entre democracia e redemocratização é historicamente prudente?", "A mudança de regime pode ampliar instituições e direitos, mas sua efetivação depende de disputas e práticas posteriores.", ["Redemocratização extingue automaticamente toda desigualdade social.", "A criação de eleições elimina a necessidade de garantir liberdades.", "Instituições novas não podem ser influenciadas por relações anteriores.", "A palavra democracia prova participação livre de todos em qualquer condição."], "Mudanças institucionais são importantes, mas não garantem por si sós acesso igual e pleno exercício de direitos. Continuidade e conflitos posteriores também precisam ser estudados."],
 ["Que cronologia é coerente com o contexto descrito?", "A Guerra Fria se desenvolve após a Segunda Guerra; processos regionais precisam ser situados dentro e além dessa disputa.", ["A Guerra Fria terminou antes da Primeira Guerra e causou seu início.", "As duas guerras mundiais ocorreram depois de todos os processos de redemocratização latino-americanos.", "A Segunda Guerra foi apenas um conflito posterior ao fim da disputa entre Estados Unidos e União Soviética.", "A Guerra Fria elimina a necessidade de localizar datas em cada país."], "A localização do contexto global ajuda a comparar processos, mas não substitui cronologias e condições específicas. Eventos anteriores e posteriores podem produzir continuidades relevantes."],
]);
export function history() {
  if (groups.length !== 20) throw Error("História: completar vinte situações");
  return Array.from({ length: 5 }, (_, variant) => groups.map((g, index) => ({ ...g[variant], family: `H${index + 1}`, variant: variant + 1 }))).flat();
}
